    private void calculatePayroll() {
        try {
            double gross = parse(txtBasicPay) + parse(txtHonorarium) + parse(txtAllowances) + parse(txtOvertime);
            double deductions = 1500 + 200 + 750 + 1471.98 + 42.61 + 1000;
            lblGrossValue.setText("₱" + currency.format(gross));
            lblDeductionsValue.setText("₱" + currency.format(deductions));
            lblNetValue.setText("₱" + currency.format(gross - deductions));
        } catch (NumberFormatException exception) {
            JOptionPane.showMessageDialog(this, "Enter valid amounts for all earnings.",
                    "Invalid amount", JOptionPane.WARNING_MESSAGE);
        }
    }

    private static double parse(JTextField field) {
        return Double.parseDouble(field.getText().trim().replace(",", "").replace("₱", ""));
    }

    private void showStatus(String message) {
        JOptionPane.showMessageDialog(this, message, "Payroll", JOptionPane.INFORMATION_MESSAGE);
    }

